<?php
declare(strict_types=1);
require_once __DIR__.'/tenant.php';
require_once __DIR__.'/auth.php';
require_once __DIR__.'/security.php';
require_once __DIR__.'/activity.php';
require_once __DIR__.'/resident_portal_lib.php';

$admin=requireAdmin();$pdo=activityDb();$content=residentPortalContent();$message='';$error='';
$query=mb_substr(trim((string)($_GET['q']??$_POST['q']??'')),0,160);
$documents=[];
try{
    $sql='SELECT d.DocumentID,COALESCE(NULLIF(d.Titel,\'\'),d.OrigineleNaam) AS Titel,d.OrigineleNaam,d.Documentdatum,m.Pad AS MapNaam FROM DocumentBibliotheek d LEFT JOIN DocumentMappen m ON m.MapID=d.MapID WHERE d.IsHuidig=1 AND d.VerwijderdOp IS NULL';
    $params=[];
    if($query!==''){$sql.=' AND (d.Titel LIKE ? OR d.OrigineleNaam LIKE ? OR m.Pad LIKE ? OR d.Tags LIKE ?)';$like='%'.$query.'%';$params=[$like,$like,$like,$like];}
    $sql.=' ORDER BY COALESCE(d.Documentdatum,d.GewijzigdOp) DESC,d.DocumentID DESC LIMIT 250';
    $stmt=$pdo->prepare($sql);$stmt->execute($params);$documents=$stmt->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){securityIncident($e);$error='De documentenlijst kon niet worden geladen.';}

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        verifyCsrf();
        $currentlyVisibleIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['visible_ids']??[])),static fn($id)=>$id>0)));
        $postedVisible=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['documents']??[])),static fn($id)=>$id>0)));
        $postedNewsletters=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['newsletter_ids']??[])),static fn($id)=>$id>0)));
        if(array_diff($postedVisible,$currentlyVisibleIds))throw new SafeInputException('Laad de documentenlijst opnieuw en probeer het nogmaals.');
        $kept=array_values(array_diff(array_map('intval',(array)$content['documents']),$currentlyVisibleIds));
        $content['documents']=array_values(array_unique([...$kept,...$postedVisible]));
        $newsletterKept=array_values(array_diff(array_map('intval',(array)$content['newsletters']),$currentlyVisibleIds));
        $content['newsletters']=array_values(array_unique(array_intersect([...$newsletterKept,...$postedNewsletters],$content['documents'])));

        $notices=[];
        foreach((array)($_POST['notice_title']??[]) as $i=>$title){$notices[]=['title'=>(string)$title,'body'=>(string)(($_POST['notice_body'][$i]??'')),'until'=>(string)(($_POST['notice_until'][$i]??'')),'active'=>isset($_POST['notice_active'][$i])];}
        $questions=(array)($_POST['qa_question']??[]);$answers=(array)($_POST['qa_answer']??[]);$qaDocs=(array)($_POST['qa_document']??[]);$qa=[];
        foreach($questions as $i=>$question){$qa[]=['question'=>(string)$question,'answer'=>(string)($answers[$i]??''),'document_id'=>(int)($qaDocs[$i]??0),'active'=>trim((string)$question)!==''&&trim((string)($answers[$i]??''))!==''];}
        $content['notices']=$notices;$content['qa']=$qa;$content['ai_enabled']=isset($_POST['ai_enabled']);
        residentPortalSaveContent($content);
        recordActivity($pdo,$admin,'bewonersportaal-inhoud-opgeslagen','bewonersportaal','inhoud','','Bewonersinhoud en vrijgegeven documenten gewijzigd.');
        $message='De bewonersinhoud is opgeslagen.';
    }catch(Throwable $e){securityIncident($e);$error=$e instanceof SafeInputException?$e->getMessage():'Opslaan is mislukt. Controleer de velden en probeer het opnieuw.';}
}
$publicDocs=residentPortalDocuments($pdo,(array)$content['documents']);
$publicDocNames=[];foreach($publicDocs as $doc)$publicDocNames[(int)$doc['DocumentID']]=(string)($doc['Titel']?:$doc['OrigineleNaam']);
function residentAdminEsc(string $value):string{return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bewonersportaal beheren · <?=residentAdminEsc((string)tenantConfig()['name'])?></title><style>
:root{--dark:#17202a;--blue:#2457a6;--line:#d5e0e8;--muted:#647180;--bg:#f3f6f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#17202a;font:14px system-ui,-apple-system,Segoe UI,Arial,sans-serif}.top{background:var(--dark);color:#fff;padding:11px 22px;display:flex;align-items:center;gap:16px}.top h1{font-size:21px;margin:0}.top small{display:block;opacity:.8}.top .links{margin-left:auto;display:flex;gap:8px}.top a{background:var(--blue);color:#fff;border:1px solid #ffffff55;padding:7px 10px;border-radius:6px;text-decoration:none;font-weight:700}.wrap{max-width:1100px;margin:20px auto;padding:0 14px}.intro{margin-bottom:16px}.intro h2{font-size:27px;margin:4px 0}.intro p{color:var(--muted);margin:0}.notice,.ok,.err{padding:11px 13px;border-radius:8px;margin-bottom:12px;line-height:1.5}.notice{background:#fff8e4;border-left:4px solid #e5a51d}.ok{background:#e9f7ed}.err{background:#fff0f0;color:#8b2d2d}.card{background:#fff;border:1px solid var(--line);border-radius:10px;margin-bottom:15px;overflow:hidden}.head{background:#eaf4fb;border-bottom:1px solid var(--line);padding:12px 15px}.head h3{font-size:17px;margin:0}.head p{margin:4px 0 0;color:var(--muted);font-size:12px}.body{padding:14px 15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;font-weight:750;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:9px 10px;border:1px solid #cbd3dc;border-radius:7px;font:inherit}.field textarea{min-height:90px;resize:vertical}.field.full{grid-column:1/-1}.row{border-bottom:1px solid #edf1f4;padding:12px 0}.row:last-child{border-bottom:0}.rowtop{display:flex;gap:12px;align-items:center}.rowtop .field{flex:1}.rowtop input[type=checkbox]{width:18px;height:18px;accent-color:var(--blue)}.tablewrap{overflow:auto}.docs{border-collapse:collapse;width:100%;min-width:730px}.docs th,.docs td{border-bottom:1px solid #edf1f4;padding:9px;text-align:left;vertical-align:middle}.docs th{background:#f8fafc;color:#516170;font-size:12px}.docs input{width:18px;height:18px;accent-color:var(--blue)}.badge{display:inline-block;border-radius:99px;padding:3px 8px;font-size:11px;font-weight:700;background:#edf1f4;color:#4c5d6c}.badge.suggest{background:#fff2d8;color:#855600}.filter{display:flex;gap:8px;margin:0 0 12px;flex-wrap:wrap}.filter input{flex:1;min-width:200px;padding:9px;border:1px solid #cbd3dc;border-radius:7px;font:inherit}.btn{border:1px solid #bfc8d2;border-radius:7px;background:#fff;padding:9px 12px;color:#17202a;text-decoration:none;font:700 13px system-ui;cursor:pointer}.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:12px}.footer{text-align:center;color:#7c8792;font-size:12px;margin:20px 0}@media(max-width:700px){.top{flex-wrap:wrap}.top .links{margin-left:0;width:100%}.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.rowtop{align-items:flex-start}.rowtop .field{min-width:0}}
</style></head><body><header class="top"><div><h1><?=tenantNameHtml()?></h1><small>Beheer bewonersportaal</small></div><div class="links"><a href="bewonersportaal.php" target="_blank" rel="noopener">Bewonersportaal bekijken ↗</a><a href="settings.php">Dropdowns beheren</a><a href="./">Database</a></div></header><main class="wrap">
<section class="intro"><h2>Inhoud voor bewoners</h2><p>Pas berichten en antwoorden aan. Vink alleen documenten aan die bewoners mogen openen.</p></section>
<?php if($message):?><div class="ok">✓ <?=residentAdminEsc($message)?></div><?php endif;?><?php if($error):?><div class="err">⚠ <?=residentAdminEsc($error)?></div><?php endif;?>
<div class="notice"><strong>Documenten delen:</strong> suggesties worden op naam en map gevonden. Ze zijn niet automatisch openbaar. Controleer de inhoud en vink alleen bestanden aan die geschikt zijn voor bewoners. Alleen de aangevinkte documenten worden via het bewonersportaal bereikbaar.</div>
<form method="post"><input type="hidden" name="csrf" value="<?=residentAdminEsc(csrfToken())?>"><input type="hidden" name="q" value="<?=residentAdminEsc($query)?>">
<section class="card"><div class="head"><h3>Berichten voor bewoners</h3><p>Lege berichten worden niet getoond. Stel eventueel een einddatum in.</p></div><div class="body">
<?php for($i=0;$i<3;$i++):$notice=(array)($content['notices'][$i]??[]);?><div class="row"><div class="grid"><div class="field"><label for="nt<?=$i?>">Titel <?=($i+1)?></label><input id="nt<?=$i?>" name="notice_title[<?=$i?>]" maxlength="180" value="<?=residentAdminEsc((string)($notice['title']??''))?>" placeholder="Bijvoorbeeld: Werkzaamheden aan de lift"></div><div class="field"><label for="nu<?=$i?>">Tonen tot (optioneel)</label><input id="nu<?=$i?>" name="notice_until[<?=$i?>]" type="date" value="<?=residentAdminEsc((string)($notice['until']??''))?>"></div><div class="field full"><label for="nb<?=$i?>">Bericht</label><textarea id="nb<?=$i?>" name="notice_body[<?=$i?>]" maxlength="3000" placeholder="Schrijf de mededeling in duidelijke, korte zinnen."><?=residentAdminEsc((string)($notice['body']??''))?></textarea></div><label><input type="checkbox" name="notice_active[<?=$i?>]" value="1"<?=!empty($notice['active'])?' checked':''?>> Actief tonen</label></div></div><?php endfor;?></div></section>
<section class="card"><div class="head"><h3>Vraagbaak (vraag en antwoord)</h3><p>De assistent gebruikt deze antwoorden en kan het gekoppelde document tonen.</p></div><div class="body"><div id="qaRows"><?php foreach((array)$content['qa'] as $i=>$qa):?><div class="row qa-row"><div class="grid"><div class="field"><label>Vraag</label><input name="qa_question[]" maxlength="500" value="<?=residentAdminEsc((string)($qa['question']??''))?>" placeholder="Voorbeeld: Waar vind ik de huisregels?"></div><div class="field"><label>Document bij het antwoord (optioneel)</label><select name="qa_document[]"><option value="0">Geen document koppelen</option><?php foreach($publicDocs as $doc):?><option value="<?=(int)$doc['DocumentID']?>"<?=(int)($qa['document_id']??0)===(int)$doc['DocumentID']?' selected':''?>><?=residentAdminEsc((string)($doc['Titel']?:$doc['OrigineleNaam']))?></option><?php endforeach;?></select></div><div class="field full"><label>Antwoord</label><textarea name="qa_answer[]" maxlength="4000" placeholder="Geef een kort, gecontroleerd antwoord."><?=residentAdminEsc((string)($qa['answer']??''))?></textarea></div><button class="btn remove-qa" type="button">Vraag verwijderen</button></div></div><?php endforeach;?></div><button class="btn" type="button" id="addQa">＋ Vraag en antwoord toevoegen</button></div></section>
<section class="card"><div class="head"><h3>Bewonersdocumenten en nieuwsbrieven</h3><p>De nieuwste drie aangevinkte nieuwsbrieven verschijnen automatisch bij Berichten voor bewoners.</p></div><div class="body"><div class="filter"><input id="docSearch" value="<?=residentAdminEsc($query)?>" placeholder="Zoek op naam of map"><button class="btn" type="button" id="filterDocs">Zoeken</button></div><div class="actions" style="margin:0 0 10px"><button class="btn" type="button" id="selectSuggested">Voorgestelde bewonersdocumenten aanvinken</button><span class="badge suggest">Alleen suggesties — controleer vóór opslaan</span></div><div class="tablewrap"><table class="docs"><thead><tr><th>Bewoners mogen openen</th><th>Nieuwsbrief</th><th>Document</th><th>Map</th><th>Voorstel</th></tr></thead><tbody>
<?php foreach($documents as $doc):$id=(int)$doc['DocumentID'];$suggested=residentPortalDocumentSuggestion((string)$doc['Titel'],(string)$doc['MapNaam']);$checked=in_array($id,array_map('intval',(array)$content['documents']),true);$newsletter=in_array($id,array_map('intval',(array)$content['newsletters']),true);?><tr><td><input type="hidden" name="visible_ids[]" value="<?=$id?>"><input type="checkbox" name="documents[]" value="<?=$id?>"<?=$checked?' checked':''?> aria-label="Bewoners toegang geven tot <?=residentAdminEsc((string)$doc['Titel'])?>"></td><td><input type="checkbox" name="newsletter_ids[]" value="<?=$id?>"<?=$newsletter?' checked':''?> aria-label="<?=residentAdminEsc((string)$doc['Titel'])?> als nieuwsbrief tonen" <?=$checked?'':'disabled'?>></td><td><strong><?=residentAdminEsc((string)$doc['Titel'])?></strong><small><?=residentAdminEsc((string)$doc['OrigineleNaam'])?></small></td><td><?=residentAdminEsc((string)$doc['MapNaam'])?></td><td><?=$suggested?'<span class="badge suggest">Mogelijk bewonersinformatie</span>':'<span class="badge">Geen voorstel</span>'?></td></tr><?php endforeach;?>
<?php if(!$documents):?><tr><td colspan="5">Geen bestanden gevonden. Pas uw zoekopdracht aan.</td></tr><?php endif;?></tbody></table></div><p class="hint">Er worden maximaal 250 resultaten tegelijk getoond. Zoek op map of documentnaam om meer bestanden te vinden. Een map- of bestandsnaam is alleen een aanwijzing, geen vrijgave.</p></div></section>
<section class="card"><div class="head"><h3>AI-zoekassistent</h3><p>De AI mag uitsluitend de hierboven vrijgegeven bewonersdocumenten gebruiken.</p></div><div class="body"><label><input type="checkbox" name="ai_enabled" value="1"<?=!empty($content['ai_enabled'])?' checked':''?>> AI-antwoorden inschakelen voor bewonersvragen</label><p class="hint">Als dit aan staat en er een externe AI-provider is ingesteld, worden bewonersvragen en passages uit vrijgegeven documenten naar die provider gestuurd. Als het uit staat, gebruikt de pagina de vraagbaak en documenttitels zonder externe AI.</p></div></section>
<div class="actions"><button class="btn primary" type="submit">Bewonersinhoud opslaan</button><span class="hint">Keuzelijsten voor soort, onderwerp, locatie en urgentie staan onder Instellingen → Dropdowns → Bewonersportaal.</span></div></form>
<p class="footer">Beheer is alleen toegankelijk voor een ingelogde administrator. Bewoners hebben geen account nodig.</p></main>
<script>
const q=document.querySelector('#docSearch');document.querySelector('#filterDocs').onclick=()=>{const url=new URL(location.href);if(q.value.trim())url.searchParams.set('q',q.value.trim());else url.searchParams.delete('q');location.href=url.toString()};q.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('#filterDocs').click()}});
document.querySelector('#selectSuggested').onclick=()=>document.querySelectorAll('.docs tbody tr').forEach(row=>{if(row.querySelector('.badge.suggest')){const access=row.querySelector('input[name="documents[]"]');const news=row.querySelector('input[name="newsletter_ids[]"]');if(access){access.checked=true;if(news)news.disabled=false}}});
document.querySelectorAll('input[name="documents[]"]').forEach(access=>access.addEventListener('change',()=>{const news=access.closest('tr')?.querySelector('input[name="newsletter_ids[]"]');if(news&&!access.checked)news.checked=false;if(news)news.disabled=!access.checked}));
document.querySelector('#addQa').onclick=()=>{const row=document.createElement('div');row.className='row qa-row';row.innerHTML='<div class="grid"><div class="field"><label>Vraag</label><input name="qa_question[]" maxlength="500" placeholder="Voorbeeld: Waar vind ik de huisregels?"></div><div class="field"><label>Document bij het antwoord (optioneel)</label><select name="qa_document[]"><option value="0">Geen document koppelen</option><?=implode('',array_map(static fn($doc)=>'<option value="'.(int)$doc['DocumentID'].'">'.residentAdminEsc((string)($doc['Titel']?:$doc['OrigineleNaam'])).'</option>',$publicDocs))?></select></div><div class="field full"><label>Antwoord</label><textarea name="qa_answer[]" maxlength="4000" placeholder="Geef een kort, gecontroleerd antwoord."></textarea></div><button class="btn remove-qa" type="button">Vraag verwijderen</button></div>';document.querySelector('#qaRows').append(row)};
document.querySelector('#qaRows').addEventListener('click',event=>{if(event.target.classList.contains('remove-qa'))event.target.closest('.qa-row')?.remove()});
</script></body></html>
